import{_ as e,o as d,c as r,a2 as a}from"./chunks/framework.CGSzHL4z.js";const u=JSON.parse('{"title":"Mouse gestures","description":"","frontmatter":{},"headers":[],"relativePath":"reference/gestures.md","filePath":"reference/gestures.md","lastUpdated":1791952279000}'),o={name:"reference/gestures.md"};function s(c,t,i,l,n,h){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="mouse-gestures" tabindex="-1">Mouse gestures <a class="header-anchor" href="#mouse-gestures" aria-label="Permalink to &quot;Mouse gestures&quot;">​</a></h1><p>Clicks, drags and modifiers in each window.</p><h3 id="timeline" tabindex="-1">Timeline <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;Timeline&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Where</th><th>Gesture</th><th>What happens</th></tr></thead><tbody><tr><td>Ruler</td><td>Drag</td><td>Scrubs; snaps to markers, keys, regions, peaks, else whole frames; <code>Alt</code> flips snapping. Plays audio snippets over sounds.</td></tr><tr><td>Ruler</td><td>Right click</td><td>Ruler menu (marker, loop, export region, insert/remove time).</td></tr><tr><td>Ruler</td><td>Middle drag, <code>Space</code>+drag</td><td>Pans time.</td></tr><tr><td>Marker flag or stem</td><td>Drag / double click / right click</td><td>Moves it (snaps) / renames it / marker menu.</td></tr><tr><td>Loop bar, export bracket</td><td>Drag body / drag an end</td><td>Moves / resizes the region.</td></tr><tr><td>Scene end handle</td><td>Drag</td><td>Changes the scene length (snaps; <code>Alt</code> flips Snap).</td></tr><tr><td>Lanes</td><td>Click a key</td><td>Selects it.</td></tr><tr><td>Lanes</td><td><code>Shift</code>+click, <code>Ctrl</code>+click a key</td><td>Adds to / toggles in the selection.</td></tr><tr><td>Lanes</td><td>Double click a main key</td><td>Selects everything under it.</td></tr><tr><td>Lanes</td><td>Drag a key</td><td>Moves the selected keys; chip and ghosts; snaps; <code>Alt</code> flips Snap.</td></tr><tr><td>Lanes</td><td><code>Ctrl</code>+drag a key</td><td>Moves a copy.</td></tr><tr><td>Lanes</td><td>Drag on empty lane</td><td>Box select; <code>Shift</code> / <code>Ctrl</code> adds.</td></tr><tr><td>Lanes</td><td>Double click empty lane space on a row</td><td>Selects every key of that row (<code>Shift</code> / <code>Ctrl</code> adds).</td></tr><tr><td>Lanes</td><td>Drag a scale handle</td><td>Retimes the selection about the other end; <code>Shift</code> about the playhead.</td></tr><tr><td>Lanes</td><td>Drag the spread handle</td><td>Offsets joints&#39; keys in time (Random / Alternate / Staircase); drag left for earlier; <code>Alt</code> exact ticks.</td></tr><tr><td>Lanes</td><td>Click the spread chip</td><td>Spread menu (mode, Reroll random).</td></tr><tr><td>Action lane</td><td>Click / <code>Shift</code>+click / <code>Ctrl</code>+click a block</td><td>Selects it / adds it / toggles it (keys let go).</td></tr><tr><td>Action lane</td><td>Drag a block</td><td>Moves the selected blocks in time (their own tracks); ghosts and a dotted trail; snaps; <code>Alt</code> flips Snap.</td></tr><tr><td>Action lane</td><td><code>Ctrl</code>+drag a block</td><td>Moves a copy.</td></tr><tr><td>Lanes, action lane</td><td>Drag a sound bar, burst bar or block up or down</td><td>Moves that bar to the lane under the pointer (with any time move, one undo step).</td></tr><tr><td>Action lane</td><td>Drag a bar&#39;s end grip</td><td>Trims that end (the other stays; at least one frame); &quot;Length 60 f&quot; read-out.</td></tr><tr><td>Action lane</td><td>Drag or double click on an empty spot</td><td>Box-selects blocks (into other rows: their keys and blocks) / selects every block of the track.</td></tr><tr><td>Action lane</td><td>Right click a block / an empty spot</td><td>Block menu / track menu (Add block at that frame).</td></tr><tr><td>Camera row</td><td>Click / <code>Shift</code>+click / <code>Ctrl</code>+click a shot</td><td>Selects its switch key / adds it / toggles it (keys and blocks let go).</td></tr><tr><td>Camera row</td><td>Drag a shot / <code>Ctrl</code>+drag</td><td>Moves the selected switch keys in time (taken frames skipped, snaps, <code>Alt</code> flips Snap) / moves a copy.</td></tr><tr><td>Camera row</td><td>Drag or double click on an empty spot</td><td>Box-selects switch keys (down into the rows: their keys and blocks instead) / selects them all.</td></tr><tr><td>Camera row</td><td>Drag a shot&#39;s right end</td><td>Cuts the shot short (its Until; no camera live to the next key); onto the next key it runs to it again.</td></tr><tr><td>Camera row</td><td>Right click a shot / an empty spot / the header</td><td>Key menu (Switch to, Start at, End at, Extend to the next switch or scene end, Duplicate, Delete, Show in Inspector) / lane menu (Switch to at that frame, Add camera at view) / header menu (Select all switch keys, Mute, Lock).</td></tr><tr><td>Lanes</td><td>Right click a key</td><td>Key menu.</td></tr><tr><td>Lanes</td><td>Right click a sound fade grip</td><td>Fade menu (shape, remove).</td></tr><tr><td>Lanes</td><td>Mouse wheel</td><td>Scrolls rows.</td></tr><tr><td>Lanes, ruler, graph</td><td><code>Ctrl</code>+wheel / <code>Shift</code>+wheel</td><td>Zooms time at the cursor / pans time.</td></tr><tr><td>Lanes</td><td><code>Ctrl+Shift</code>+wheel</td><td>Compact or normal rows.</td></tr><tr><td>Lanes, ruler, graph</td><td>Middle drag, <code>Space</code>+drag</td><td>Pans.</td></tr><tr><td>Sound bar</td><td>Drag left edge / right edge</td><td>Trims the start (audio stays put) / trims the end.</td></tr><tr><td>Sound bar</td><td>Double click the right edge</td><td>Clears the end trim.</td></tr><tr><td>Sound bar</td><td><code>Ctrl</code>+drag the right edge</td><td>Stretches the speed (0.25x to 4x).</td></tr><tr><td>Sound bar</td><td>Drag a fade grip / a loop handle</td><td>Fades / moves the loop.</td></tr><tr><td>Effect bar</td><td>Drag the end grip / the min knob</td><td>Max life / min life; double click a grip for the emitter&#39;s own.</td></tr><tr><td>Row header</td><td>Click / <code>Ctrl</code>+click / <code>Shift</code>+click / <code>Ctrl+Shift</code>+click</td><td>Select / toggle / range / add range.</td></tr><tr><td>Row header</td><td>Double click</td><td>Keys the row at the playhead (like <code>K</code>).</td></tr><tr><td>Row header</td><td>Right click</td><td>Row menu.</td></tr><tr><td>Row header (sound/effect rows)</td><td>Drag top or bottom edge</td><td>Taller or shorter row; double click resets.</td></tr><tr><td>Row header</td><td>Hover</td><td>Shows the mute (eye) and lock buttons.</td></tr><tr><td>Splitter (Split)</td><td>Drag</td><td>Shares the room between dope rows and curves.</td></tr><tr><td>Curve graph</td><td>Click / <code>Shift</code> / <code>Ctrl</code> a key</td><td>Selects / adds / toggles.</td></tr><tr><td>Curve graph</td><td>Drag selected keys</td><td>Moves in time and value; <code>Shift</code> keeps one direction; <code>Alt</code> flips snapping.</td></tr><tr><td>Curve graph</td><td>Drag a tangent handle</td><td>Shapes both sides; <code>Alt</code> shapes one side.</td></tr><tr><td>Curve graph</td><td>Wheel / <code>Ctrl</code>+wheel / <code>Shift</code>+wheel / <code>Ctrl+Shift</code>+wheel</td><td>Pans values / zooms time / pans time / zooms values.</td></tr><tr><td>Curve graph</td><td>Wheel over the value axis</td><td>Zooms values at the pointer.</td></tr><tr><td>Ease canvas</td><td>Drag a handle</td><td>Shapes the ease live; <code>Shift</code> snaps 0.05; <code>Alt</code> ignores snapping.</td></tr><tr><td>Ease presets</td><td>Click a card / right click a saved card</td><td>Applies it / deletes it (after a confirm).</td></tr><tr><td>Status bar</td><td>Click snap, auto-key, fps, length</td><td>Opens the menu or toggles.</td></tr><tr><td>Toolbar</td><td>Click a tool&#39;s chevron</td><td>The tool&#39;s options menu.</td></tr><tr><td>Any control</td><td>Hover</td><td>Tooltip (0.5 s delay, then instant across neighbours); disabled controls say why.</td></tr></tbody></table><h3 id="hub" tabindex="-1">Hub <a class="header-anchor" href="#hub" aria-label="Permalink to &quot;Hub&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Where</th><th>Gesture</th><th>What happens</th></tr></thead><tbody><tr><td>Scene row</td><td>Click / double click</td><td>Opens it / renames it in place.</td></tr><tr><td>Scene row</td><td>Hover</td><td>Rename, Duplicate, Delete buttons.</td></tr><tr><td>Cast row</td><td>Click / double click / right click</td><td>Selects / renames / menu.</td></tr><tr><td>Cast row chip</td><td>Click</td><td>Align menu.</td></tr><tr><td>Cast row</td><td>Hover</td><td>Mute (eye) and lock buttons.</td></tr></tbody></table><h3 id="inspector" tabindex="-1">Inspector <a class="header-anchor" href="#inspector" aria-label="Permalink to &quot;Inspector&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Where</th><th>Gesture</th><th>What happens</th></tr></thead><tbody><tr><td>Number field</td><td>Click</td><td>Types a value.</td></tr><tr><td>Number field</td><td>Drag left/right</td><td>Scrubs; <code>Shift</code> finer (10x); <code>Ctrl</code> whole numbers; <code>Esc</code> reverts.</td></tr><tr><td>Property row</td><td>Right click anywhere</td><td>Row menu.</td></tr><tr><td>Key diamond</td><td>Click</td><td>Animate / key / remove key / key a change.</td></tr><tr><td>Property row</td><td>Hover + <code>K</code></td><td>Keys it.</td></tr><tr><td>Section header</td><td>Click</td><td>Folds it (remembered per class).</td></tr><tr><td>Color3 swatch, sequence/gradient preview</td><td>Click</td><td>Opens the editor window.</td></tr><tr><td>Texture palette swatch</td><td>Click</td><td>Swaps the image.</td></tr><tr><td>Stack entry</td><td>Click</td><td>Opens its block&#39;s panel (the Attached entry: its attach key).</td></tr><tr><td>Stack entry</td><td>Right click</td><td>Its block menu.</td></tr><tr><td>Stack entry</td><td>Drag up/down</td><td>Changes the order it runs in; <code>Esc</code> puts it back.</td></tr><tr><td>Stack entry eye</td><td>Click</td><td>Mutes or unmutes it.</td></tr></tbody></table><h3 id="editor-windows" tabindex="-1">Editor windows <a class="header-anchor" href="#editor-windows" aria-label="Permalink to &quot;Editor windows&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Where</th><th>Gesture</th><th>What happens</th></tr></thead><tbody><tr><td>Hue ring / square</td><td>Drag</td><td>Sets hue / saturation and brightness.</td></tr><tr><td>Sequence graph</td><td>Click</td><td>Adds a point and keeps dragging it.</td></tr><tr><td>Sequence point</td><td>Drag / right click</td><td>Moves it (<code>Shift</code> snaps time) / removes it.</td></tr><tr><td>Envelope bar</td><td>Drag</td><td>Widens or narrows the spread.</td></tr><tr><td>Gradient bar</td><td>Click</td><td>Adds a stop.</td></tr><tr><td>Gradient stop</td><td>Drag / right click / double click</td><td>Moves / removes / opens its colour picker.</td></tr><tr><td>Saved swatch</td><td>Click / right click</td><td>Applies / rename and delete menu.</td></tr></tbody></table><h3 id="viewport" tabindex="-1">Viewport <a class="header-anchor" href="#viewport" aria-label="Permalink to &quot;Viewport&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Where</th><th>Gesture</th><th>What happens</th></tr></thead><tbody><tr><td>Body part / joint dot / bone</td><td>Click</td><td>Picks it; <code>Ctrl</code> adds or removes.</td></tr><tr><td>Empty space</td><td>Click</td><td>Clears the pick and Studio&#39;s selection.</td></tr><tr><td>Outside the scene</td><td>Click, <code>Alt</code>+click</td><td>Selects the model / the part itself in Studio; <code>Ctrl</code> toggles.</td></tr><tr><td>Gizmo handle</td><td>Drag</td><td>Turns or moves the picked joints; <code>Ctrl</code> flips the snapping; <code>Esc</code> or right click cancels.</td></tr><tr><td>Resize handle</td><td>Drag</td><td>Resizes; <code>Ctrl</code> both sides; <code>Alt</code> keeps proportions; <code>Esc</code> cancels.</td></tr><tr><td>Part (IK on)</td><td>Press and drag</td><td>IK drag of its chain.</td></tr><tr><td>Hold <code>P</code> + click</td><td>Part / joint dot / floor or prop</td><td>Pins a spot / the whole part / anchors the picked parts&#39; pins.</td></tr><tr><td>Hold <code>Tab</code></td><td>Over a part</td><td>Temporary pivot.</td></tr><tr><td>Hold <code>I</code></td><td>While dragging</td><td>Flips FK/IK.</td></tr><tr><td>Hold <code>J</code></td><td>Over a trail</td><td>Timing mode.</td></tr><tr><td>Trail dot / handle / line</td><td>Click / drag / double click the line</td><td>Picks / reshapes / adds a key.</td></tr></tbody></table>',12)])])}const k=e(o,[["render",s]]);export{u as __pageData,k as default};
